"""페드로 로드리게스 설명(NOTE) 문장. build_pedro.py가 숫자를 넘겨 부른다."""

def d_(s):
    y, m, d = s.split("-"); return f"{int(y)}.{int(m)}.{int(d)}"

KO = {"BATE Borisov": "BATE 보리소프", "CE L'Hospitalet": "로스피탈레트(국왕컵)", "Elche CF": "엘체(국왕컵)", "Grimsby Town": "그림즈비 타운(리그컵)",
      "Feyenoord Rotterdam": "페예노르트", "AC Milan": "AC 밀란", "Inter Milan": "인테르", "ACF Fiorentina": "피오렌티나", "Genoa CFC": "제노아"}

def make_note(v):
    M, E, ST, CK = v["M"], v["E"], v["ST"], v["CLUB_KO"]
    c3 = lambda x: "·".join(map(str, x[:3]))
    X = v["EXCL_CNT"]
    pk = ", ".join(d_(r[9]) + " " + KO[r[1]] + "전" for r in E if r[8])
    S = v["SRC"]
    L = [
        f"페드로 로드리게스(바르셀로나·첼시·AS 로마·라치오)의 클럽 공식 경기 {v['NG']}경기({d_(M[0][0])} 레알 무르시아전 ~ {d_(M[-1][0])} 피사전)에서 나온 {v['NGo']}골 {v['NA']}도움(PK 골 {v['NPK']}개), 친선경기·스페인 대표팀(A·U21)·바르셀로나 B·C 경기 제외",
        "클럽별 경기·골·도움: " + ", ".join(f"{CK[k]} {c3(x)}" for k, x in ST.items()) + f". 출전 분 합계 {v['MIN_TOT']:,}분",
        "출처: 경기 목록·출전 분(연장·퇴장 반영)은 Transfermarkt 선수 경기 성적, 골 시간·골 뒤 스코어·PK·도움은 Transfermarkt 경기 리포트(골·도움이 있는 경기 전부와 리그 밖 경기 전부)를 쓰고, 2010-11부터는 FotMob 경기 이벤트와 대조함(FotMob에는 2009-10 이전 바르셀로나 경기와 2010.8.21 수페르코파 자료가 없음). 경기 수·골은 스페인어·영어 위키백과 클럽·시즌·대회별 기록과 모두 같음",
        "바르셀로나 B(2006-07·2008-09 스페인 3부, Transfermarkt 18경기 10골, 위키백과 2007-08 포함 55경기 17골)와 바르셀로나 C(스페인 4부, 위키백과 71경기 11골)는 2군·3군이고 프로 리그도 아니어서 넣지 않음",
        "출전 분은 모두 Transfermarkt 그대로(90분 추정 없음). 몰수 경기 2개는 실제로 뛴 경기와 분으로 셈: 2020.9.19 엘라스 베로나전(0:0 경기, 출전 자격 없는 선수 기용으로 0:3 몰수패, 90분), 2021.1.19 스페치아전(코파 이탈리아 16강, 연장 끝에 2:4로 졌고 교체 6명 규정 위반으로 0:3 몰수패, 95분). 두 경기 모두 골·도움 없음. 2017.8.6 커뮤니티 실드 아스널전은 80분 퇴장(FotMob 90분), 2019.8.14 UEFA 슈퍼컵 리버풀전은 Transfermarkt 120분(FotMob 90분)으로 Transfermarkt를 따름",
        "골: 2010-11 이후 골은 Transfermarkt와 FotMob이 수·분·PK 여부가 같음(FotMob이 90·45분으로만 적은 추가시간은 Transfermarkt 표기). PK 골: " + pk,
        f"도움: 2014년 8월 전(바르셀로나 2013-14까지)은 Transfermarkt 리포트 도움(FotMob 도움 기록이 이 시기에 많이 비어 있음), 이후는 Transfermarkt와 FotMob 경기 이벤트가 함께 센 것 + 한쪽에만 있으면 다른 출처 2곳이 확인한 것. 도움 {v['NA']} = Transfermarkt {v['N_TM_A']} − PK 유도 {X['PK 유도']}(2011.3.8 아스널·2012.9.15 헤타페·2013.2.3 발렌시아 메시, 2013.12.22 헤타페·2014.1.8 헤타페 국왕컵 파브레가스, 2020.10.18 베네벤토·2020.10.26 밀란 베레투, 2023.1.24 밀란 루이스 알베르토) − 'Shot on goal'(슈팅 리바운드) {X[chr(39) + 'Shot on goal' + chr(39) + '(슈팅 리바운드)']}(2013.12.6 카르타헤나 동구, 2014.5.3 헤타페 알렉시스, 2020.12.3 영보이스 마요랄, 2026.4.27 우디네세 말디니) − 상대 자책골에 준 도움 {X['상대 자책골에 준 도움']}(2010.1.10 테네리페 루나, 2010.5.16 바야돌리드 프리에토, 2010.8.21 세비야 콩코) − 개별 판정 {X['개별 판정']} + FotMob에만 있고 다른 출처가 확인한 1",
        "개별 판정으로 뺀 도움: 2011.2.5 아틀레티코전 29분 메시 골(Transfermarkt는 페드로 도움, FotMob과 경기 기사는 다비드 비야 도움 — 비야 기록에 도움이 들어 있어 한 골에 도움 두 개가 되지 않게 뺌), 2022.11.6 로마전(더비) 29분 펠리피 안데르송 골(Transfermarkt만 도움; 경기 기사는 페드로의 압박에 이바녜스가 잘못 내준 공으로 적어 패스 도움이 분명하지 않음)",
        "FotMob에만 있는 도움: 2022.4.10 제노아전 76분 임모빌레 골은 Transfermarkt가 '도움 없음'이지만 FotMob과 이탈리아 경기 기사 2곳(Quotidiano.net·Tuttomercatoweb)이 페드로가 연결한 것으로 적어 넣음. 2026.4.27 우디네세전 90+5분 말디니 골은 FotMob이 페드로 도움으로 세지만 Transfermarkt는 페드로 슈팅이 튀어 나온 공(리바운드)으로 적고 기사도 갈려 넣지 않음",
        "2012.1.22 말라가전 메시 세 번째 골(페드로 도움) 시각은 Transfermarkt 77분 대신 FotMob 82분(ESPN·말라가 구단 81분)을 씀. 2014년 8월 전 도움은 Transfermarkt 한 곳 기준이라 모두를 다른 출처와 대조하지는 않음",
        "도움 합계 비교: Transfermarkt 113·FotMob 경력 합계 94(바르셀로나 47·첼시 26·로마 4·라치오 17; 2010-14 도움 칸 일부 비어 있음)·이 계산기 " + str(v["NA"]),
        "날짜는 현지 날짜(Transfermarkt 리포트 날짜). 클럽 월드컵 2009(아부다비)·2011(일본)은 개최지 날짜",
        f"상대 Elo는 같은 경기를 다룬 다른 선수 자료(메시·이니에스타·비야·네이마르·수아레스·아자르·파브레가스·임모빌레 등) 값, 같은 팀·같은 시즌 다른 선수 자료 값, 그 시즌 최종 순위(Transfermarkt 순위표)에 맞춘 다른 선수 자료의 같은 리그·같은 순위 값, 직접 추정 순으로 씀(기록 {len(E)}개: 같은 경기 {S['같은 경기 다른 선수 자료']}, 같은 팀·시즌 {S['팀×시즌 통합표']}, 순위·추정 {S['직접 추정']})",
        "순위로 맞춘 값: 월솔 2015-16 리그 원 3위 1555, 피터버러 2016-17 리그 원 11위 1491, 브렌트퍼드 2016-17 챔피언십 10위 1617, 울버햄프턴 2016-17 챔피언십 15위 1584, 노팅엄 포리스트 2019-20 챔피언십 7위 1642, AZ 2022-23 에레디비시 4위 1642, 나폴리 2024-25 세리에A 1위 1969. 직접 추정(모두 '추정'): 말뫼 2018 스웨덴 3위 1529, 슬라비아 프라하 2018-19 체코 1위 1600, 디나모 키이우 2018-19 우크라이나 2위 1620, CFR 클루지 2020-21 루마니아 1위 1500(모두 다른 선수 자료의 같은 팀·같은 순위 값)",
        "대회 비중: 코파 델 레이·FA컵·리그컵·코파 이탈리아는 국내컵(16강까지 낮은 비중, 8강 이후 높은 비중; FA컵 6라운드는 8강), 수페르코파(두 경기 결승)·UEFA 슈퍼컵·커뮤니티 실드는 국내컵 결승, 수페르코파 이탈리아나 2024 준결승(인테르전)은 국내컵 준결승, 클럽 월드컵 2009·2011은 단판. 유로파 32강(intermediate stage)은 유로파 토너먼트, 2024-25 유로파 리그 단계는 조별과 같게, 컨퍼런스 2022-23 녹아웃 플레이오프·16강은 컨퍼런스 토너먼트로 계산함",
        f"두 경기 합산(챔스·유로파·컨퍼런스 토너먼트와 예선, 코파 델 레이 32강~준결승, 수페르코파, 리그컵·코파 이탈리아 준결승) 기록 {v['NTIE']}개({v['NTIEG']}경기)는 합산 S로 계산함. 원정 다득점은 UEFA 대회 2020-21까지, 코파 델 레이·수페르코파(이 선수 경기는 모두 2015년 전) 적용, 리그컵 준결승 2017-18까지, 코파 이탈리아 2021-22까지. 페드로가 뛰지 않은 다른 차전 스코어는 Transfermarkt 경기 리포트로 채움",
        "시즌 구분은 모든 클럽 8월 1일 기준(첼시 2020.8.1 FA컵 결승은 2019-20, 2015.8.11 UEFA 슈퍼컵·2015.8.14/17 수페르코파는 바르셀로나 2015-16). 클럽 구분은 2015.8.20 전 바르셀로나(마지막 경기 2015.8.17 아틀레틱 빌바오전), 2020.9.1 전 첼시(마지막 경기 2020.8.1 FA컵 결승 아스널전), 2021.8.19 전 AS 로마, 이후 라치오",
        "수상 기록은 Transfermarkt 업적 페이지 기준: 챔스 3회(2008-09·2010-11·2014-15), 유로파리그 2018-19, UEFA 슈퍼컵 3회(2009-10·2011-12·2015-16), 클럽 월드컵 2회(2009-10·2011-12, Transfermarkt 표기 2010·2012), 라리가 5회(2008-09·2009-10·2010-11·2012-13·2014-15), 프리미어리그 2016-17, 코파 델 레이 3회(2008-09·2011-12·2014-15), FA컵 2018, 수페르코파 4회(2009-10·2010-11·2011-12·2013-14). 월드컵·유로 등 대표팀 기록은 뺌",
        "은퇴: 2026.7.1 라치오와 계약이 끝나고 2026.10.7 은퇴(Transfermarkt). 마지막 출전·반영 경기 2026.5.23 피사전(2026.11.13 수집)",
    ]
    return "\n".join(L)
